// Start gameplay once without guessing between multiple controls or following links.
export async function startForCapture(page, { enabled = true, selector = '', timeout = 3000 } = {}) {
  if (!enabled) return { clicked: false, reason: 'disabled' }
  const candidate = selector
    ? page.locator(selector)
    : page.locator('button, input[type="button"], input[type="submit"], [role="button"]')
  const deadline = Date.now() + timeout
  do {
    const matches = []
    for (const control of await candidate.all()) {
      if (!await control.isVisible() || !await control.isEnabled()) continue
      const eligible = await control.evaluate((element, explicit) => {
        if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false
        if (explicit) return true
        const label = element.getAttribute('aria-label') || element.value || element.textContent || ''
        return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
      }, Boolean(selector))
      if (eligible) matches.push(control)
    }
    if (matches.length > 1) return { clicked: false, reason: 'ambiguous' }
    if (matches.length === 1) {
      try { await matches[0].click({ trial: true, timeout: 2000 }) }
      catch (error) {
        if (error.name === 'TimeoutError') return { clicked: false, reason: 'not-actionable' }
        throw error
      }
      await matches[0].click({ timeout: 2000, noWaitAfter: true })
      return { clicked: true }
    }
    if (Date.now() >= deadline) break
    await page.waitForTimeout(Math.min(200, Math.max(0, deadline - Date.now())))
  } while (Date.now() <= deadline)
  return { clicked: false, reason: 'not-found' }
}

Capture will click a button whose accessible text exactly "Start" or "Play" or "Start Game" or "Play Game". If our button says "START ENGINE", not matched. Could set aria-label="Start Game" and text "START ENGINE" but capture checks aria-label first, so "Start Game" matches. Good. Then screenshot after 1s of gameplay. Need game scene visible, not start screen. Ensure clicking start hides overlay immediately and camera transitions. After 1s, scene shows truck from chase camera. Good.

Capture uses `page.screenshot`, page errors fail if strict maybe. Need no console errors. Also requests 404 fail if strict. Ensure no missing files.

Could also use CSS animations but respect reduced motion.

Let's write index.html, styles.css, src/main.js. Need vendor three. Download three.module.js to vendor. It's ~1.2MB. Fine. Ensure module import `./vendor/three.module.js` from src/main.js path `../vendor/three.module.js`.

Maybe include `favicon.svg` to avoid 404? Browser requests /favicon.ico automatically? Capture failure tracks response status >=400 same origin. Chromium may request favicon.ico and get 404 -> failure if strict. Add `<link rel="icon" href="data:image/svg+xml,...">` to avoid request. Or create favicon.svg and link. We'll add inline data URI or file. Better file `favicon.svg` and link. But if strict checks only page responses, favicon fetched and 200. We'll create.

