    camera.position.lerp(cameraDesired, 1 - Math.exp(-dt * 2.1));
    cameraLook.set(truck.position.x, 1.7, truck.position.z);
    camera.lookAt(cameraLook);
    camera.fov = damp(camera.fov, 52, 2, dt);
