Now part 4b: updateVehicle, goal, start/reset/pause/finish, listeners, animate/init. Need ensure functions referenced before definitions okay.

Let's write:

```js
function resetRun() { ... }
function startGame() { ... }
function resumeGame() { ... }
function restartRun() { ... }
function pauseGame() { ... }
function togglePause() { ... }
function toggleMute() { ... }
function finishRun() { ... }
function showCompleteScreen() { ... }
function updateVehicle(dt) { ... }
function checkGoal() { ... }
function update(dt) { ... }
function animate() { ... }
function onResize() { ... }
function bindKeyboard() { ... }
function init() { ... }
```

Detailed updateVehicle:
```
function updateVehicle(dt) {
  const offRoad = Math.abs(truck.position.x) > ROAD_HALF + 0.8;
  const speedAbs = Math.abs(vehicle.speed);
  const speedFactor = clamp(speedAbs / MAX_SPEED, 0, 1);
  const maxSteer = 0.58 * (1 - speedFactor * 0.52);
  const targetSteer = input.steer * maxSteer;
  vehicle.steer = damp(vehicle.steer, targetSteer, input.steer === 0 ? 8 : 5.5, dt);

  let acceleration = 0;
  if (input.throttle) {
    if (vehicle.speed < -0.4) acceleration += 16;
    else acceleration += 7.4 * (1 - clamp(vehicle.speed / MAX_SPEED, 0, 0.94) * 0.58);
  }
  if (input.brake) {
    if (vehicle.speed > 0.4) acceleration -= 19;
    else acceleration -= 5.2;
  }
  if (!input.throttle && !input.brake) {
    const rolling = 1.05 + speedAbs * 0.075;
    acceleration -= Math.sign(vehicle.speed) * Math.min(speedAbs / Math.max(dt, 0.001), rolling);
  }
  acceleration -= vehicle.speed * 0.025;
  if (offRoad) acceleration -= Math.sign(vehicle.speed) * (2.8 + speedAbs * 0.18);
  vehicle.acceleration = acceleration;
  vehicle.speed += acceleration * dt;
  const maxForward = offRoad ? 11 : MAX_SPEED;
  const maxReverse = offRoad ? 5 : MAX_REVERSE;
  vehicle.speed = clamp(vehicle.speed, -maxReverse, maxForward);
  if (Math.abs(vehicle.speed) < 0.035 && !input.throttle && !input.brake) vehicle.speed = 0;

  if (Math.abs(vehicle.speed) > 0.04) {
    vehicle.heading += (vehicle.speed / 4.85) * Math.tan(vehicle.steer) * dt;
  }
  const forwardX = -Math.sin(vehicle.heading);
  const forwardZ = -Math.cos(vehicle.heading);
  truck.position.x += forwardX * vehicle.speed * dt;
  truck.position.z += forwardZ * vehicle.speed * dt;
  truck.position.x = clamp(truck.position.x, -150, 150);
  truck.position.z = clamp(truck.position.z, -1520, 90);
  truck.rotation.y = vehicle.heading;
  truck.updateMatrixWorld(true);

  const targetRoll = -vehicle.steer * clamp(speedAbs / MAX_SPEED, 0, 1) * 0.24;
  const targetPitch = -acceleration * 0.006;
  truckVisual.rotation.z = damp(truckVisual.rotation.z, targetRoll, 5.5, dt);
  truckVisual.rotation.x = damp(truckVisual.rotation.x, targetPitch, 5.5, dt);
  const bob = offRoad && speedAbs > 1 ? Math.sin(performance.now() * 0.03) * 0.012 * speedAbs : 0;
  truckVisual.position.y = damp(truckVisual.position.y, bob, 12, dt);

  const spinDelta = (vehicle.speed * dt) / 0.5;
  for (const wheel of wheels) {
    wheel.spin.rotation.x += spinDelta;
    if (wheel.steerable) wheel.pivot.rotation.y = vehicle.steer;
  }

  state.topSpeed = Math.max(state.topSpeed, speedAbs * 3.6);

  // dust
  const shouldDust = (offRoad && speedAbs > 2.5) || (input.brake && speedAbs > 11);
  if (shouldDust) {
    dustTimer -= dt;
    if (dustTimer <= 0) {
      dustTimer = 0.035;
      const rearZ = 2.7;
      const lateral = 0.95;
      for (const side of [-1,1]) {
        const lx = side*lateral;
        const wx = truck.position.x + Math.cos(vehicle.heading)*lx + Math.sin(vehicle.heading)*rearZ; // check transform
        const wz = truck.position.z - Math.sin(vehicle.heading)*lx + Math.cos(vehicle.heading)*rearZ;
        spawnDust(wx, 0.18, wz, offRoad?1:0.55);
      }
    }
  } else {
    dustTimer = 0;
  }
}
```

Check local-to-world transform for a point (lx, y, lz) with rotation.y = heading:
world x = truck.x + lx*cos(h) + lz*sin(h)
world z = truck.z - lx*sin(h) + lz*cos(h)
Because rotation matrix around Y: x' = x*cos + z*sin; z' = -x*sin + z*cos. Yes. For rear (lz=+2.7 behind, since truck forward -Z, rear is +Z), world x += sin(h)*2.7, z += cos(h)*2.7. Correct. Good.

But `truck.position.x` is 2.8 and heading 0, rear dust at x 2.8±0.95, z 22.7. Good.

Wheel spin sign: forward speed positive should spin wheels forward. Visual not critical.

`checkGoal`:
```
const inZone = Math.abs(truck.position.z - DEST_Z) < 14 && Math.abs(truck.position.x) < 5.9;
if (inZone && Math.abs(vehicle.speed) < 1.25 && Math.abs(truck.position.z - DEST_Z) < 13) finishRun();
```
- Maybe require stopped for 0.4s to avoid instant at crossing? Could trigger while passing through slowly. That's fine; stopping in zone. If speed <1.25, close enough. Add `state.zoneTime`? Not needed.
- If in zone and speed > 1.25, hint shows stop. Good.

`update(dt)`:
```
state.showcaseTime += dt;
for clouds...
if (state.mode==='playing') { state.time += dt; readInput(); updateVehicle(dt); checkGoal(); }
else if (state.mode==='complete') { state.completeTime += dt; if (state.completeDelay>0) { state.completeDelay-=dt; if (state.completeDelay<=0) showCompleteScreen(); } }
else { input.throttle=0; input.brake=0; input.steer=0; }
updateDust(dt); updateConfetti(dt);
updateCamera(dt);
updateHud();
updateHint(dt);
// sun follow
sun.position.set(truck.position.x + 55, 90, truck.position.z + 40);
sun.target.position.set(truck.position.x, 0, truck.position.z - 10);
sun.target.updateMatrixWorld();
// sky follows camera
sky.position.copy(camera.position);
// zone pulse
